presetParts.perFrame:
st = max (0, st-0.2/fps);
dec = 1-0.5/fps;
st_ = st_* (dec) + (1-dec)*st;

//dir
dir = 0.7*sin(time*.0162+rany*6);
q2 = dir+0.5; 
q3 = sin(dir);
q4 = cos(dir);

//scaling plane
q7 = 0.002;

//movement
posx = time*0.0003;
posy = time*0.004;
q10 = posx;
q11 = posy;

//start ran for warp mod 
q15 = ranx;
q16 = rany;

test = (t0-time)*0.047-3.14/2;
view = 0.7 + min(1, max (-1, 2*sin(test)))*0.17;

//Alti
q8 = 4 + 3* sin(test) + (view-0.55)*16;

//hory (Kippung)
q6 = view * (1-st_) + st_*2;

//q6  = 0.55;
monitor = view;

waves.frame_eqs_str:
vol = bass*8 + mid*5 + treb*3;
m = m*0.97 + vol*0.08;
monitor = vol;
beat = above(vol,res)*above(vol,m)*above(vol,16);
diff = (1-beat)*diff + beat*(vol-res);
res = beat*(vol + m*0.04) + (1-beat)*(res -  (0.1+diff*0.02)*60/fps);
res = max(0,res);
b = beat;
g = 1-beat;

waves.point_eqs_str:
w = sample*asin(1)*4;
d = 0.04;
x = 0.5 + sin(w)*d;
y = 0.5 + cos(w)*d;

sample = 1-sample;
xxx = xx;
yyy = yy;
xx = pow(sample,5)*t1 + 5*pow(sample,4)*(1-sample)*t1 + 10*pow(sample,3)*sqr(1-sample)*t2
+ 10*sqr(sample)*pow(1-sample,3)*t3 + 5*pow(1-sample,4)*sample*t4 + pow(1-sample,5)*t4;

yy = pow(sample,5)*t5 + 5*pow(sample,4)*(1-sample)*t5 + 10*pow(sample,3)*sqr(1-sample)*t6
+ 10*sqr(sample)*pow(1-sample,3)*t7 + 5*pow(1-sample,4)*sample*t8 + pow(1-sample,5)*t8;
d = 1/sqrt(sqr(xx-xxx)+sqr(yy-yyy));
x = xx + sample*(1-sample)*(value1-value2)*(yy-yyy)*d;
y = yy - sample*(1-sample)*(value1-value2)*(xx-xxx)*d;

